data.transform:
($payloads:=
[$state.context.REMOTE.(
  $remoteId:=id;
  $remoteExternalId:=externalid;
  $internalWorkcenterId:= $coalesce([$remoteExternalId, $state.context.LOCAL.workcenter[externalId = $string($remoteId)].id, $cuid() ]) ;
  $internalGroupId:= $coalesce([$state.context.LOCAL.workcenter[externalId = $string($remoteId)].workcenterGroup.id, $cuid() ]) ;
  $remoteLocationId:=custentityworkcenter_location;
  $currentFacilityId := $state.context.LOCAL.facility[externalId = $string($remoteLocationId)].id;
  {
  "workcenterGroup":{
    "create": {
      "name": groupname,
      "usable": isinactive='F',
      "integrationData": $,
      "facilityId": $currentFacilityId,
      "externalId": $string(id)

    },
    "update": {
      "name": groupname,
      "usable": isinactive='F',
      "integrationData": $,
      "facilityId": $currentFacilityId,
      "externalId": $string(id)
    },
    "where": {
      "id": $internalGroupId
    }
  },
  "workcenter":{
    "create": {
      "name": groupname,
      "code":  groupname & "(" & $string(id) & ")",
      "description": comments,
      "shiftGroupId": "Default",
      "modeGroupId": "Default",
      "active": isinactive='F',
      "integrationData": $,
      "facilityId": $currentFacilityId,
      "workcenterGroupId":$internalGroupId,
      "externalId": $string(id),
      "workcenterTypeId": "Production"
    },
    "update": {
      "name": groupname,
      "code":  groupname & "(" & $string(id) & ")",
      "description": comments,
      "shiftGroupId": "Default",
      "modeGroupId": "Default",
      "active": isinactive='F',
      "integrationData": $,
      "facilityId": $currentFacilityId,
      "workcenterGroupId":$internalGroupId,
      "externalId": $string(id),
      "workcenterTypeId": "Production"
    },
    "where": {
      "id": $internalWorkcenterId
    }
  }
  }


  )];
{"wcg":$payloads.workcenterGroup,
"wc":$payloads.workcenter
}
)

