  "msg": {
    "create":{
      "integrationId": $state.context.REQUEST.DATA.integration.id,
      "modelId": $state.context.REQUEST.DATA.model.id,
      "message": $state.context.REQUEST.DATA.model.name
        & " synchronization failed. Following error returned by query: " & $string(error),
      "typeId": "Failure",
      "data": $state
    }
  }
}

data.query:
query Query($workcenterWhere: WorkcenterWhereInput ,$where: FacilityWhereInput, $orderBy: [FacilityOrderByInput!], $first: Int, $after: String) {
  facility(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
        externalId
      }
    }
  }
  workcenter(where: $workcenterWhere) {
    edges {
      node {
        id
        code
        active
        externalId
        name
        workcenterGroup{
          id
          externalId
        }
      }
    }
  }
}

data.mutation:
mutation upsertWorkcenter(
  $wcg: [WorkcenterGroupUpsertPayloadInput!]!
  $wc:[WorkcenterUpsertPayloadInput!]!
){

  upsertWorkcenterGroup(payload:$wcg){id}
  upsertWorkcenter(payload:$wc) {
  id
  externalId
}

}

